WITH department_stats AS (SELECT dept_id, SUM(CASE WHEN level = 'L4' THEN salary ELSE 0 END) AS l4_salary FROM employees WHERE full_name LIKE 'O%' GROUP BY dept_id) SELECT departments.location, departments.dept_name, department_stats.l4_salary FROM departments LEFT OUTER JOIN department_stats ON departments.id = department_stats.dept_id WHERE department_stats.l4_salary > 36 ORDER BY location;
